CREATE TABLE quotes (id INT AUTO_INCREMENT PRIMARY KEY, token VARCHAR(64) NOT NULL UNIQUE, quoteNumber VARCHAR(32) NOT NULL UNIQUE, customerName VARCHAR(200), customerEmail VARCHAR(320), customerPhone VARCHAR(50), title VARCHAR(300) NOT NULL, description TEXT, items JSON, referenceImages JSON, subtotal DECIMAL(10,2) NOT NULL, total DECIMAL(10,2) NOT NULL, notes TEXT, status VARCHAR(20) NOT NULL DEFAULT 'draft', orderId INT, expiresAt TIMESTAMP NULL, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
